{
  "page": {
    "title": "Checkout story",
    "sections": [
      {
        "id": "checkout",
        "heading": "Customer checkout",
        "diagram": {
          "view": "step",
          "autoplay": false,
          "nodes": {
            "customer": {
              "title": "Customer"
            },
            "payment": {
              "title": "Payment"
            },
            "shipping": {
              "title": "Shipping"
            },
            "refunds": {
              "title": "Refunds"
            }
          },
          "rows": [
            [
              "customer",
              "payment",
              "shipping",
              "refunds"
            ]
          ],
          "edges": [
            {
              "from": "customer",
              "to": "payment",
              "kind": "https"
            },
            {
              "from": "payment",
              "to": "shipping",
              "kind": "https"
            }
          ],
          "panels": [
            {
              "id": "status",
              "type": "state",
              "states": [
                "unknown",
                "paid",
                "failed"
              ],
              "initial": {
                "state": "unknown"
              }
            }
          ],
          "steps": [
            {
              "id": "submit",
              "text": "Customer submits payment",
              "edge": "customer->payment"
            },
            {
              "id": "timeout",
              "text": "The payment result is unknown after the timeout",
              "nodes": [
                "payment"
              ],
              "panels": {
                "status": {
                  "state": "unknown"
                }
              }
            },
            {
              "id": "success",
              "text": "A separately confirmed payment is accepted",
              "nodes": [
                "payment"
              ],
              "panels": {
                "status": {
                  "state": "paid"
                }
              }
            }
          ],
          "paths": [
            {
              "id": "timeout",
              "label": "Unknown result",
              "steps": [
                "submit",
                "timeout"
              ]
            },
            {
              "id": "confirmed",
              "label": "Confirmed success",
              "steps": [
                "submit",
                "success"
              ]
            }
          ],
          "layouts": [
            {
              "id": "story",
              "name": "Story",
              "steps": [
                "submit",
                "timeout"
              ],
              "sectionLayout": {
                "default": [
                  {
                    "diagram": true,
                    "x": 0,
                    "y": 0,
                    "w": 12,
                    "h": 8
                  },
                  {
                    "panel": "status",
                    "x": 0,
                    "y": 8,
                    "w": 12,
                    "h": 3
                  }
                ]
              }
            },
            {
              "id": "engineering",
              "name": "Engineering",
              "steps": [
                "submit",
                "timeout",
                "success"
              ],
              "sectionLayout": {
                "default": [
                  {
                    "diagram": true,
                    "x": 0,
                    "y": 0,
                    "w": 12,
                    "h": 8
                  },
                  {
                    "panel": "status",
                    "x": 0,
                    "y": 8,
                    "w": 12,
                    "h": 3
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "billing",
        "heading": "Account billing",
        "diagram": {
          "nodes": {
            "payment": {
              "title": "Payment"
            }
          },
          "rows": [
            [
              "payment"
            ]
          ]
        }
      }
    ]
  }
}

